const VignetteShader = {
    uniforms: {
        tDiffuse: { value: null },
        offset: { value: 1.0 },
        darkness: { value: 1.0 },
    },
    vertexShader: `varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,
    fragmentShader: `
        uniform sampler2D tDiffuse;
        uniform float offset;
        uniform float darkness;
        varying vec2 vUv;
        void main(){
            vec4 texel=texture2D(tDiffuse,vUv);
            vec2 uv=(vUv-vec2(0.5))*vec2(offset);
            float vig=clamp(1.0-dot(uv,uv),0.0,1.0);
            texel.rgb*=mix(1.0,pow(vig,0.5),darkness);
            gl_FragColor=texel;
        }`,
}

const ChromaticAberrationShader = {
    uniforms: {
        tDiffuse: { value: null },
        strength: { value: 0.005 },
        resolution: { value: new THREE.Vector2(1, 1) },
    },
    vertexShader: `varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,
    fragmentShader: `
        uniform sampler2D tDiffuse;
        uniform float strength;
        uniform vec2 resolution;
        varying vec2 vUv;
        void main(){
            vec2 dir=vUv-vec2(0.5);
            float d=length(dir);
            float s=strength*d*d;
            vec2 offset=dir*s;
            float r=texture2D(tDiffuse,vUv+offset).r;
            float g=texture2D(tDiffuse,vUv).g;
            float b=texture2D(tDiffuse,vUv-offset).b;
            float a=texture2D(tDiffuse,vUv).a;
            gl_FragColor=vec4(r,g,b,a);
        }`,
}

const FilmGrainShader = {
    uniforms: {
        tDiffuse: { value: null },
        time: { value: 0.0 },
        intensity: { value: 0.05 },
    },
    vertexShader: `varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,
    fragmentShader: `
        uniform sampler2D tDiffuse;
        uniform float time;
        uniform float intensity;
        varying vec2 vUv;
        float rand(vec2 co){return fract(sin(dot(co,vec2(12.9898,78.233)))*43758.5453);}
        void main(){
            vec4 texel=texture2D(tDiffuse,vUv);
            float noise=rand(vUv+vec2(time*0.01,time*0.007))*2.0-1.0;
            texel.rgb+=noise*intensity;
            gl_FragColor=texel;
        }`,
}

/**
 * AlphaRestoreShader — restores original alpha from a saved render target.
 * UnrealBloomPass destroys alpha (writes 1.0 everywhere via AdditiveBlending).
 * This pass takes RGB from the post-processed chain but alpha from the pre-bloom render.
 */
const AlphaRestoreShader = {
    uniforms: {
        tDiffuse: { value: null },
        tAlpha: { value: null },
    },
    vertexShader: `varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,
    fragmentShader: `
        uniform sampler2D tDiffuse;
        uniform sampler2D tAlpha;
        varying vec2 vUv;
        void main(){
            vec4 color=texture2D(tDiffuse,vUv);
            float alpha=texture2D(tAlpha,vUv).a;
            gl_FragColor=vec4(color.rgb*alpha, alpha);
        }`,
}

/**
 * AlphaSavePass — copies current readBuffer to a side render target (alphaRT)
 * to preserve alpha before bloom destroys it. Passes through unchanged.
 */
class AlphaSavePass {
    enabled: boolean = true
    needsSwap: boolean = false
    renderToScreen: boolean = false
    clear: boolean = false
    targetRT: THREE.WebGLRenderTarget
    private _copyMat: THREE.ShaderMaterial
    private _fsQuad: any
    private _scene: THREE.Scene
    private _cam: THREE.OrthographicCamera

    constructor(targetRT: THREE.WebGLRenderTarget) {
        this.targetRT = targetRT
        this._copyMat = new THREE.ShaderMaterial({
            uniforms: { tDiffuse: { value: null } },
            vertexShader: `varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,
            fragmentShader: `uniform sampler2D tDiffuse;varying vec2 vUv;void main(){gl_FragColor=texture2D(tDiffuse,vUv);}`,
            depthTest: false,
            depthWrite: false,
        })
        const geo = new THREE.PlaneGeometry(2, 2)
        this._fsQuad = new THREE.Mesh(geo, this._copyMat)
        this._fsQuad.frustumCulled = false
        this._scene = new THREE.Scene()
        this._scene.add(this._fsQuad)
        this._cam = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1)
    }

    setSize(w: number, h: number) {
        this.targetRT.setSize(w, h)
    }

    render(renderer: THREE.WebGLRenderer, writeBuffer: any, readBuffer: any) {
        if (!this.enabled) return
        this._copyMat.uniforms.tDiffuse.value = readBuffer.texture
        const oldRT = renderer.getRenderTarget()
        renderer.setRenderTarget(this.targetRT)
        renderer.clear()
        renderer.render(this._scene, this._cam)
        renderer.setRenderTarget(oldRT)
    }

    dispose() {
        this._copyMat.dispose()
        this._fsQuad.geometry.dispose()
        this.targetRT.dispose()
    }
}

const ColorGradingShader = {
    uniforms: {
        tDiffuse: { value: null },
        brightness: { value: 0.0 },
        contrast: { value: 1.0 },
        saturation: { value: 1.0 },
    },
    vertexShader: `varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,
    fragmentShader: `
        uniform sampler2D tDiffuse;
        uniform float brightness;
        uniform float contrast;
        uniform float saturation;
        varying vec2 vUv;
        void main(){
            vec4 texel=texture2D(tDiffuse,vUv);
            texel.rgb+=brightness;
            texel.rgb=((texel.rgb-0.5)*contrast)+0.5;
            float lum=dot(texel.rgb,vec3(0.2126,0.7152,0.0722));
            texel.rgb=mix(vec3(lum),texel.rgb,saturation);
            gl_FragColor=vec4(max(texel.rgb,0.0),texel.a);
        }`,
}

/* ═══════════════════════════════════════════════════════════
   Reusable temp objects — avoid per-frame GC allocations
   ═══════════════════════════════════════════════════════════ */

const _tmpVec3A = new THREE.Vector3()
const _tmpVec3B = new THREE.Vector3()
const _tmpParticleVecA = new THREE.Vector3()
const _tmpParticleVecB = new THREE.Vector3()
const _tmpBox3 = new THREE.Box3()
const _tmpStereoSize = new THREE.Vector2()
const _tmpSubScenePivotOffset = new THREE.Vector3()
const _tmpSubScenePivotEuler = new THREE.Euler()
const _tmpSubScenePivotQuat = new THREE.Quaternion()

/** Orthographic frustum half-size (world units). Zoom controls magnification. */
const _ORTHO_FRUSTUM = 10

/** Desktop auto-fit cap keeps published wide viewports from scaling models larger than the Framer canvas. */
const _AUTO_FIT_MAX_ASPECT = 1.42

/** Get visible width/height at a given distance from camera (works for both perspective & ortho). */
function _getVisibleSize(camera: any, distance: number) {
    if (camera.isOrthographicCamera) {
        const w = (camera.right - camera.left) / camera.zoom
        const h = (camera.top - camera.bottom) / camera.zoom
        return { width: w, height: h }
    }
    const fov = camera.fov * (Math.PI / 180)
    const h = 2 * Math.tan(fov / 2) * distance
    const w = h * camera.aspect
    return { width: w, height: h }
}

/**
 * Auto-fit should be stable between Framer canvas and published desktop.
 * Published pages are often wider than the editor canvas; without this cap,
 * width-limited models grow larger after publish.
 */
function _getAutoFitVisibleSize(camera: any, distance: number) {
    const visible = _getVisibleSize(camera, distance)
    const cappedWidth =
        visible.height *
        Math.min(camera.aspect || _AUTO_FIT_MAX_ASPECT, _AUTO_FIT_MAX_ASPECT)
    return {
        width: Math.min(visible.width, cappedWidth),
        height: visible.height,
    }
}

function _getAutoFitRatio(camera: any, normSize: THREE.Vector3) {
    const camDist = camera.position.length()
    const { width: visibleWidth, height: visibleHeight } =
        _getAutoFitVisibleSize(camera, camDist)
    return (
        Math.min(
            visibleWidth / Math.max(normSize.x, 0.0001),
            visibleHeight / Math.max(normSize.y, 0.0001)
        ) * 0.85
    )
}

/** Cap render DPR to avoid expensive full-resolution rendering on high-DPI displays. */
function _getOptimizedDpr(cfg: any) {
    if (typeof window === "undefined") return 1
    const raw = window.devicePixelRatio || 1
    let cap = cfg.performanceMode
        ? (cfg.performanceDprCap ?? 1.5)
        : (cfg.performanceDprCap ?? 2)
    const isMobileLike =
        window.matchMedia?.("(pointer: coarse)")?.matches ||
        window.innerWidth <= 768
    if (isMobileLike && cfg.performanceMobileDprCap != null) {
        cap = Math.min(cap, cfg.performanceMobileDprCap)
    }
    return Math.max(0.5, Math.min(raw, cap))
}

/* ── Dispose a sub-scene (remove from Three.js scene, free GPU resources) ── */
function disposeSubScene(st, ss) {
    if (ss.group) {
        st.scene.remove(ss.group)
        // Materials only — geometries shared with _modelCache
        _disposeMaterialsOnly(ss.group)
    }
    ss._animationWarmupDone = false
    if (ss.mixer) {
        _clearAnimationOnceCompleteListener(ss, ss.mixer)
        ss.mixer.stopAllAction()
    }
}

/* ── Singleton Loaders (avoid re-creating per load call) ── */
let _sharedDraco = null
let _sharedGLTF = null
let _sharedFBX = null

/* ── Track last successfully loaded model URL to prevent re-broadcast on remount ── */
let _lastLoadedModelUrl: string | null = null

/* ── Parsed Model Cache — avoids GLTF re-parse + GPU re-upload on URL revisit ── */
interface _CachedModel {
    scene: THREE.Object3D
    animations: THREE.AnimationClip[]
}
const _modelCache = new Map<string, _CachedModel>()

/**
 * Check if an Object3D tree contains any SkinnedMesh (armature/skeleton).
 */
function _hasSkinnedMesh(object: THREE.Object3D): boolean {
    let found = false
    object.traverse((child: any) => {
        if (child.isSkinnedMesh) found = true
    })
    return found
}

/**
 * Compute bounding box from mesh geometries only (excludes Bone, Light, Helper objects).
 * For skinned meshes, uses geometry bounding box in world space to avoid bone-inflated bounds.
 */
function _computeMeshOnlyBoundingBox(object: THREE.Object3D): THREE.Box3 {
    object.updateWorldMatrix(true, true)
    const box = new THREE.Box3()
    let hasMesh = false
    object.traverse((child: any) => {
        if ((child.isMesh || child.isSkinnedMesh) && child.visible) {
            if (child.geometry) {
                if (!child.geometry.boundingBox)
                    child.geometry.computeBoundingBox()
                if (
                    child.geometry.boundingBox &&
                    !child.geometry.boundingBox.isEmpty()
                ) {
                    const geomBox = child.geometry.boundingBox.clone()
                    geomBox.applyMatrix4(child.matrixWorld)
                    box.union(geomBox)
                    hasMesh = true
                }
            }
        }
    })
    if (!hasMesh) {
        box.setFromObject(object)
    }
    return box
}

/**
 * Clean up a loaded scene that contains SkinnedMesh (armature models).
 * - Hides duplicate non-skinned Mesh that shares geometry with SkinnedMesh (bind-pose duplicate)
 * - Hides Mesh parented under Bone (bone visualization helpers / custom bone shapes)
 * - Hides very small helper meshes (bone markers, cubes, points)
 */
function _cleanupSkinnedScene(object: THREE.Object3D): void {
    if (!_hasSkinnedMesh(object)) return

    const skinnedGeometries = new Set()
    object.traverse((child: any) => {
        if (child.isSkinnedMesh && child.geometry) {
            skinnedGeometries.add(child.geometry)
        }
    })

    object.traverse((child: any) => {
        if (!child.isMesh || child.isSkinnedMesh) return

        // Hide regular Mesh that shares geometry with a SkinnedMesh (bind-pose duplicate)
        if (child.geometry && skinnedGeometries.has(child.geometry)) {
            child.visible = false
            return
        }

        // Hide Mesh parented under a Bone (custom bone shape / bone helper)
        let p = child.parent
        while (p) {
            if (p.isBone) {
                child.visible = false
                return
            }
            p = p.parent
        }

        // Hide very small helper meshes (bone markers)
        if (child.geometry) {
            if (!child.geometry.boundingBox) child.geometry.computeBoundingBox()
            const bb = child.geometry.boundingBox
            if (bb) {
                const sz = bb.getSize(_tmpVec3A)
                if (Math.max(sz.x, sz.y, sz.z) < 0.001) {
                    child.visible = false
                    return
                }
            }
        }
    })
}

/**
 * Deep-clone a scene's Object3D hierarchy with independent material instances.
 * Uses SkeletonUtils.clone for scenes with SkinnedMesh to preserve skeleton binding.
 * Geometries & textures: shared by reference (no re-parse/re-upload).
 * Materials: cloned per instance (safe to modify & dispose independently).
 */
function _cloneSceneWithMaterials(source: THREE.Object3D): THREE.Object3D {
    const clone = _hasSkinnedMesh(source)
        ? SkeletonUtils.clone(source)
        : source.clone(true)
    clone.traverse((child: any) => {
        if (child.isMesh && child.material) {
            if (Array.isArray(child.material)) {
                child.material = child.material.map((m) => m.clone())
            } else {
                child.material = child.material.clone()
            }
        }
    })
    return clone
}

/**
 * Clone a cached model for fresh use.
 */
function _cloneCachedModel(cached: _CachedModel): {
    scene: THREE.Object3D
    animations: THREE.AnimationClip[]
} {
    return {
        scene: _cloneSceneWithMaterials(cached.scene),
        animations: cached.animations.map((clip) => clip.clone()),
    }
}

/**
 * Dispose ONLY materials (not geometries/textures) from a model group.
 * Used when model came from cache — geometries are shared with cache.
 */
function _disposeMaterialsOnly(group: THREE.Object3D) {
    group.traverse((c: any) => {
        if (c.isMesh) {
            ;(Array.isArray(c.material) ? c.material : [c.material]).forEach(
                (m) => m.dispose?.()
            )
            _origMaterialBackups.delete(c.uuid)
        }
    })
}

/**
 * Full dispose: geometries + materials + textures. Used when clearing cache.
 */
function _disposeModelFull(group: THREE.Object3D) {
    group.traverse((c: any) => {
        if (c.isMesh) {
            c.geometry?.dispose()
            ;(Array.isArray(c.material) ? c.material : [c.material]).forEach(
                (m) => {
                    const texKeys = [
                        "map",
                        "normalMap",
                        "roughnessMap",
                        "metalnessMap",
                        "aoMap",
                        "emissiveMap",
                        "envMap",
                        "lightMap",
                        "alphaMap",
                        "bumpMap",
                        "displacementMap",
                    ]
                    for (const k of texKeys) {
                        if (m[k]) m[k].dispose?.()
                    }
                    m.dispose?.()
                }
            )
            _origMaterialBackups.delete(c.uuid)
        }
    })
}

/** Clear entire model cache and free GPU resources */
function _clearModelCache() {
    for (const [, cached] of _modelCache) {
        _disposeModelFull(cached.scene)
    }
    _modelCache.clear()
    _preloadInFlight.clear()
    _preloadBatchTotal = 0
    _preloadBatchDone = 0
}

/* ── Eager Preload System ──
 * Starts downloading + parsing model immediately (before Three.js init).
 * Result is stored in _modelCache so the load-model effect finds a cache hit.
 * Deduplicates concurrent requests for the same URL.
 */
const _preloadInFlight = new Map<string, Promise<void>>()

/** Track how many preload requests were initiated vs completed in a batch */
let _preloadBatchTotal = 0
let _preloadBatchDone = 0

/**
 * Synthetic progress animation for when Content-Length is missing
 * Uses asymptotic curve: progress approaches 90% but never reaches it.
 * Gives visual feedback on slow networks where real progress events don't fire.
 */
let _syntheticProgressTimer: any = null
let _syntheticProgressStart = 0
let _hasRealProgress = false

function _startSyntheticProgress() {
    _hasRealProgress = false
    _syntheticProgressStart = performance.now()
    if (_syntheticProgressTimer) cancelAnimationFrame(_syntheticProgressTimer)

    const tick = () => {
        if (_hasRealProgress) return // real progress took over
        const mls =
            typeof window !== "undefined"
                ? (window as any).__modelLoadingState
                : null
        if (!mls || !mls.isLoading || mls.isComplete) return

        // Asymptotic curve: 1 - e^(-t/k), capped at 0.85
        // k=8 means ~63% at 8s, ~78% at 12s, ~85% at 15s — feels natural
        const elapsed = (performance.now() - _syntheticProgressStart) / 1000
        const synthetic = (1 - Math.exp(-elapsed / 8)) * 0.85
        mls.setProgress(synthetic)
        _syntheticProgressTimer = requestAnimationFrame(tick)
    }

    // Start after 500ms delay — give real progress events a chance to fire first
    setTimeout(() => {
        if (!_hasRealProgress) {
            _syntheticProgressTimer = requestAnimationFrame(tick)
        }
    }, 500)
}

function _stopSyntheticProgress() {
    if (_syntheticProgressTimer) {
        cancelAnimationFrame(_syntheticProgressTimer)
        _syntheticProgressTimer = null
    }
}

function _startModelPreload(url: string): Promise<void> {
    if (!url) return Promise.resolve()
    if (_modelCache.has(url)) return Promise.resolve()
    if (_preloadInFlight.has(url)) return _preloadInFlight.get(url)!

    const format = detectFormat(url)

    // Broadcast loading state immediately so splash screen knows to wait
    if (typeof window !== "undefined" && (window as any).__modelLoadingState) {
        const mls = (window as any).__modelLoadingState
        if (!mls.isLoading && !mls.isComplete) {
            mls.setLoading()
        }
    }

    // Track batch count
    _preloadBatchTotal++

    // Start synthetic progress animation (gives visual feedback when Content-Length is missing)
    if (_preloadBatchTotal === 1) _startSyntheticProgress()

    const promise = new Promise<void>((resolve) => {
        const _checkBatchComplete = () => {
            // When ALL in-flight preloads are done, set progress to 95%
            // but do NOT call setComplete() — that's the load-model effect's job
            // after the model is actually added to the Three.js scene and visible.
            if (
                _preloadInFlight.size === 0 &&
                typeof window !== "undefined" &&
                (window as any).__modelLoadingState
            ) {
                const mls = (window as any).__modelLoadingState
                if (mls.isLoading && !mls.isComplete) {
                    _stopSyntheticProgress()
                    mls.setProgress(0.95)
                }
                // Reset batch counters
                _preloadBatchTotal = 0
                _preloadBatchDone = 0
            }
        }

        const onDone = (object: any, animations?: any[]) => {
            if (!_modelCache.has(url)) {
                // Clean up skinned mesh artifacts before caching so all clones inherit clean state
                _cleanupSkinnedScene(object)
                _modelCache.set(url, {
                    scene: object, // preload owns this instance — no need to clone
                    animations: (animations || []).map((c) => c.clone()),
                })
            }
            _preloadInFlight.delete(url)
            _preloadBatchDone++
            _checkBatchComplete()
            resolve()
        }

        const onProgress = (event: any) => {
            if (!event.lengthComputable) return
            // Real progress received — kill synthetic animation
            if (!_hasRealProgress) {
                _hasRealProgress = true
                _stopSyntheticProgress()
            }
            const pct = event.loaded / event.total
            if (
                typeof window !== "undefined" &&
                (window as any).__modelLoadingState
            ) {
                // Scale progress across batch: each URL gets an equal share
                const batchTotal = Math.max(_preloadBatchTotal, 1)
                const perUrlShare = 1 / batchTotal
                const overallPct = (_preloadBatchDone + pct) * perUrlShare
                ;(window as any).__modelLoadingState.setProgress(
                    Math.min(overallPct * 0.95, 0.95)
                )
            }
        }

        const onErr = (err: any) => {
            console.warn("[Preload] Failed for", url, err)
            _preloadInFlight.delete(url)
            _preloadBatchDone++
            _checkBatchComplete()
            resolve() // resolve anyway — load-model effect will retry or show error
        }

        try {
            if (format === "zip") _loadFromZip(url, onDone, onProgress, onErr)
            else if (format === "fbx")
                getSharedFBXLoader().load(
                    url,
                    (obj) => onDone(obj, obj.animations || []),
                    onProgress,
                    onErr
                )
            else
                getSharedGLTFLoader().load(
                    url,
                    (g) => onDone(g.scene, g.animations),
                    onProgress,
                    onErr
                )
        } catch (err) {
            onErr(err)
        }
    })

    _preloadInFlight.set(url, promise)
    return promise
}

// Expose globally so splash screen or external scripts can trigger preload early
if (typeof window !== "undefined") {
    ;(window as any).__preloadModel3D = _startModelPreload
}

/** Direct model load with caching — used as fallback when preload didn't cover a URL */
function _loadModelDirect(
    url: string,
    format: string | null,
    onLoaded: Function,
    onProgress?: Function,
    onError?: Function
) {
    if (format === "zip") {
        _loadFromZip(
            url,
            (object, animations) => {
                _cleanupSkinnedScene(object)
                if (!_modelCache.has(url)) {
                    _modelCache.set(url, {
                        scene: _cloneSceneWithMaterials(object),
                        animations: (animations || []).map((c) => c.clone()),
                    })
                }
                onLoaded(object, animations)
            },
            onProgress as any,
            onError as any
        )
        return
    }
    if (format === "fbx") {
        getSharedFBXLoader().load(
            url,
            (obj) => {
                const animations = obj.animations || []
                _cleanupSkinnedScene(obj)
                if (!_modelCache.has(url)) {
                    _modelCache.set(url, {
                        scene: _cloneSceneWithMaterials(obj),
                        animations: animations.map((c) => c.clone()),
                    })
                }
                onLoaded(obj, animations)
            },
            onProgress as any,
            onError as any
        )
        return
    }
    getSharedGLTFLoader().load(
        url,
        (g) => {
            _cleanupSkinnedScene(g.scene)
            if (!_modelCache.has(url)) {
                _modelCache.set(url, {
                    scene: _cloneSceneWithMaterials(g.scene),
                    animations: g.animations.map((c) => c.clone()),
                })
            }
            onLoaded(g.scene, g.animations)
        },
        onProgress as any,
        onError as any
    )
}

function getSharedGLTFLoader() {
    if (!_sharedGLTF) {
        _sharedDraco = new DRACOLoader()
        _sharedDraco.setDecoderPath(
            "https://www.gstatic.com/draco/versioned/decoders/1.5.7/"
        )
        _sharedGLTF = new GLTFLoader()
        _sharedGLTF.setDRACOLoader(_sharedDraco)
    }
    return _sharedGLTF
}

function getSharedFBXLoader() {
    if (!_sharedFBX) {
        _sharedFBX = new FBXLoader()
    }
    return _sharedFBX
}

/* ═══════════════════════════════════════════════════════════
   ZIP Archive Support
   ═════════════════���═════════════════════════════════════════
   Extracts ZIP containing GLB/GLTF model files (+bin+textures)
   and loads via blob URLs with a custom LoadingManager.
*/

/** Cache of extracted ZIP blob URLs to avoid re-extracting the same ZIP */
const _zipBlobCache = new Map<
    string,
    {
        blobMap: Record<string, string>
        mainFile: string
        mainFormat: string
    }
>()

/**
 * Load a 3D model from a ZIP archive URL.
 *
 * Flow:
 *  1. Fetch ZIP as ArrayBuffer (with progress callback for download phase)
 *  2. Extract all files using JSZip → create blob URLs
 *  3. Detect main model file inside (priority: .glb > .gltf > .fbx)
 *  4. Create a custom THREE.LoadingManager that redirects resource requests to blob URLs
 *  5. Load via GLTFLoader or FBXLoader → call onLoaded(object, animations)
 *  7. Cache extracted blob URLs for reuse
 */
async function _loadFromZip(
    zipUrl: string,
    onLoaded: (object: any, animations?: any[]) => void,
    onProgress?: (event: {
        loaded: number
        total: number
        lengthComputable: boolean
    }) => void,
    onError?: (err: any) => void
) {
    try {
        let blobMap: Record<string, string>
        let mainFile: string
        let mainFormat: string

        // ── Check ZIP blob cache ──
        const cached = _zipBlobCache.get(zipUrl)
        if (cached) {
            blobMap = cached.blobMap
            mainFile = cached.mainFile
            mainFormat = cached.mainFormat
        } else {
            // ── Phase 1: Download ZIP ──
            const response = await fetch(zipUrl)
            if (!response.ok)
                throw new Error(
                    `Failed to fetch ZIP: ${response.status} ${response.statusText}`
                )

            const contentLength = parseInt(
                response.headers.get("content-length") || "0",
                10
            )
            const reader = response.body?.getReader()
            if (!reader) throw new Error("ReadableStream not supported")

            const chunks: Uint8Array[] = []
            let receivedLength = 0

            while (true) {
                const { done, value } = await reader.read()
                if (done) break
                chunks.push(value)
                receivedLength += value.length
                if (onProgress && contentLength > 0) {
                    // Download phase = 0% – 80% of total progress
                    onProgress({
                        loaded: receivedLength * 0.8,
                        total: contentLength,
                        lengthComputable: true,
                    })
                }
            }

            // Concatenate chunks into single ArrayBuffer
            const zipBuffer = new Uint8Array(receivedLength)
            let offset = 0
            for (const chunk of chunks) {
                zipBuffer.set(chunk, offset)
                offset += chunk.length
            }

            // ── Phase 2: Extract ZIP ──
            const zip = await JSZip.loadAsync(zipBuffer.buffer)

            // Find all files and create blob URLs
            blobMap = {}
            const fileEntries: Array<{ path: string; file: any }> = []

            zip.forEach((relativePath: string, zipEntry: any) => {
                if (!zipEntry.dir) {
                    fileEntries.push({
                        path: relativePath,
                        file: zipEntry,
                    })
                }
            })

            // Detect main model file (priority: .glb > .gltf > .fbx)
            const MODEL_EXTENSIONS = [".glb", ".gltf", ".fbx"]
            let mainEntry: { path: string; ext: string } | null = null

            for (const ext of MODEL_EXTENSIONS) {
                const found = fileEntries.find((e) =>
                    e.path.toLowerCase().endsWith(ext)
                )
                if (found) {
                    mainEntry = { path: found.path, ext: ext.slice(1) } // remove dot
                    break
                }
            }

            if (!mainEntry) {
                throw new Error(
                    "ZIP does not contain a supported 3D model file (.glb, .gltf, .fbx)."
                )
            }

            mainFile = mainEntry.path
            mainFormat = mainEntry.ext

            // Extract all files to blob URLs
            for (let i = 0; i < fileEntries.length; i++) {
                const { path, file } = fileEntries[i]
                const ext = path.toLowerCase().split(".").pop() || ""

                // Determine MIME type for blob
                let mimeType = "application/octet-stream"
                if (ext === "gltf" || ext === "json")
                    mimeType = "application/json"
                else if (ext === "glb") mimeType = "model/gltf-binary"
                else if (ext === "bin") mimeType = "application/octet-stream"
                else if (ext === "png") mimeType = "image/png"
                else if (ext === "jpg" || ext === "jpeg")
                    mimeType = "image/jpeg"
                else if (ext === "webp") mimeType = "image/webp"
                else if (ext === "hdr") mimeType = "application/octet-stream"
                else if (ext === "fbx") mimeType = "application/octet-stream"

                const blob = await file.async("blob")
                const typedBlob = new Blob([blob], { type: mimeType })
                const blobUrl = URL.createObjectURL(typedBlob)

                // Map by full path (as it appears in the ZIP)
                blobMap[path] = blobUrl
                // Map by filename only (for resolving relative refs)
                const filename = path.split("/").pop()!
                blobMap[filename] = blobUrl
                // Map by lowercase variants
                blobMap[path.toLowerCase()] = blobUrl
                blobMap[filename.toLowerCase()] = blobUrl

                if (onProgress && contentLength > 0) {
                    // Extraction phase = 80% – 95%
                    const extractPct = 0.8 + (i / fileEntries.length) * 0.15
                    onProgress({
                        loaded: extractPct * contentLength,
                        total: contentLength,
                        lengthComputable: true,
                    })
                }
            }

            // Cache the blob map for reuse
            _zipBlobCache.set(zipUrl, {
                blobMap,
                mainFile,
                mainFormat,
            })
        }

        // ── Phase 3: Load model from blob URLs ──
        const mainBlobUrl = blobMap[mainFile] || blobMap[mainFile.toLowerCase()]
        if (!mainBlobUrl) {
            throw new Error(
                `Could not find blob URL for main model file: ${mainFile}`
            )
        }

        // Create a custom LoadingManager that redirects resource requests to blob URLs
        const manager = new THREE.LoadingManager()
        manager.setURLModifier((url: string) => {
            // If it's already a blob URL we created, pass through
            if (url.startsWith("blob:")) return url

            const normalized = url.replace(/\\/g, "/")

            // Try direct match
            if (blobMap[normalized]) return blobMap[normalized]

            // Try filename only (handles absolute paths from FBX exports, etc.)
            const filename = normalized.split("/").pop() || ""
            if (blobMap[filename]) return blobMap[filename]

            // Try lowercase
            if (blobMap[normalized.toLowerCase()])
                return blobMap[normalized.toLowerCase()]
            if (blobMap[filename.toLowerCase()])
                return blobMap[filename.toLowerCase()]

            // Try decoding URI components
            try {
                const decoded = decodeURIComponent(filename)
                if (blobMap[decoded]) return blobMap[decoded]
                if (blobMap[decoded.toLowerCase()])
                    return blobMap[decoded.toLowerCase()]
            } catch {}

            return url // fallback to original URL
        })

        // Load model with custom manager for resource resolution
        if (mainFormat === "fbx") {
            const fbxLoader = new FBXLoader(manager)
            fbxLoader.load(
                mainBlobUrl,
                (obj) => onLoaded(obj, obj.animations || []),
                undefined,
                (err) => {
                    if (onError) onError(err)
                }
            )
        } else {
            const gltfLoader = new GLTFLoader(manager)
            const draco = new DRACOLoader()
            draco.setDecoderPath(
                "https://www.gstatic.com/draco/versioned/decoders/1.5.7/"
            )
            gltfLoader.setDRACOLoader(draco)

            gltfLoader.load(
                mainBlobUrl,
                (gltf) => onLoaded(gltf.scene, gltf.animations),
                undefined,
                (err) => {
                    if (onError) onError(err)
                }
            )
        }
    } catch (err) {
        console.error("[ZIP] Failed to load model from ZIP:", err)
        if (onError) onError(err)
    }
}

/* ═══════════════════════════════════════════════════════════
   Emissive Dissolve Effect (for model transitions)
   ══════════════════════��════════════════════════════════════ */

// Simple 3D noise function (Perlin-like)
const noiseGLSL = `
    vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
    vec4 mod289(vec4 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
    vec4 permute(vec4 x) { return mod289(((x*34.0)+1.0)*x); }
    vec4 taylorInvSqrt(vec4 r) { return 1.79284291400159 - 0.85373472095314 * r; }
    
    float snoise(vec3 v) {
        const vec2 C = vec2(1.0/6.0, 1.0/3.0);
        const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);
        vec3 i  = floor(v + dot(v, C.yyy));
        vec3 x0 = v - i + dot(i, C.xxx);
        vec3 g = step(x0.yzx, x0.xyz);
        vec3 l = 1.0 - g;
        vec3 i1 = min(g.xyz, l.zxy);
        vec3 i2 = max(g.xyz, l.zxy);
        vec3 x1 = x0 - i1 + C.xxx;
        vec3 x2 = x0 - i2 + C.yyy;
        vec3 x3 = x0 - D.yyy;
        i = mod289(i);
        vec4 p = permute(permute(permute(
            i.z + vec4(0.0, i1.z, i2.z, 1.0))
            + i.y + vec4(0.0, i1.y, i2.y, 1.0))
            + i.x + vec4(0.0, i1.x, i2.x, 1.0));
        float n_ = 0.142857142857;
        vec3 ns = n_ * D.wyz - D.xzx;
        vec4 j = p - 49.0 * floor(p * ns.z * ns.z);
        vec4 x_ = floor(j * ns.z);
        vec4 y_ = floor(j - 7.0 * x_);
        vec4 x = x_ *ns.x + ns.yyyy;
        vec4 y = y_ *ns.x + ns.yyyy;
        vec4 h = 1.0 - abs(x) - abs(y);
        vec4 b0 = vec4(x.xy, y.xy);
        vec4 b1 = vec4(x.zw, y.zw);
        vec4 s0 = floor(b0)*2.0 + 1.0;
        vec4 s1 = floor(b1)*2.0 + 1.0;
        vec4 sh = -step(h, vec4(0.0));
        vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy;
        vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww;
        vec3 p0 = vec3(a0.xy, h.x);
        vec3 p1 = vec3(a0.zw, h.y);
        vec3 p2 = vec3(a1.xy, h.z);
        vec3 p3 = vec3(a1.zw, h.w);
        vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2,p2), dot(p3,p3)));
        p0 *= norm.x;
        p1 *= norm.y;
        p2 *= norm.z;
        p3 *= norm.w;
        vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
        m = m * m;
        return 42.0 * dot(m*m, vec4(dot(p0,x0), dot(p1,x1), dot(p2,x2), dot(p3,x3)));
    }
`

function createDissolveMaterial(originalMaterial, dissolveConfig) {
    const {
        progress,
        noiseScale,
        edgeWidth,
        emissiveColor,
        emissiveIntensity,
        amplitude,
    } = dissolveConfig

    const mat = originalMaterial.clone()

    // Store dissolve properties (readable before shader compiles)
    mat.userData.dissolveProgress = progress
    mat.userData.noiseScale = noiseScale // frequency
    mat.userData.amplitude = amplitude ?? 16 // noise multiplier
    mat.userData.edgeWidth = edgeWidth
    mat.userData.emissiveColor = parseColor(emissiveColor)
    mat.userData.emissiveIntensity = emissiveIntensity

    mat.onBeforeCompile = (shader) => {
        shader.uniforms.uProgress = {
            value: mat.userData.dissolveProgress,
        }
        shader.uniforms.uFreq = { value: mat.userData.noiseScale }
        shader.uniforms.uAmp = { value: mat.userData.amplitude }
        shader.uniforms.uEdge = { value: mat.userData.edgeWidth }
        shader.uniforms.uEdgeColor = {
            value: mat.userData.emissiveColor,
        }
        shader.uniforms.uEdgeIntensity = {
            value: mat.userData.emissiveIntensity,
        }

        mat.userData.shaderUniforms = shader.uniforms

        // ── Vertex: pass object-space position to fragment ──
        shader.vertexShader = shader.vertexShader.replace(
            "#include <common>",
            `#include <common>
varying vec3 vPos;`
        )
        shader.vertexShader = shader.vertexShader.replace(
            "#include <begin_vertex>",
            `#include <begin_vertex>
vPos = position;`
        )

        // ── Fragment: inject noise, dissolve discard, edge glow ──
        shader.fragmentShader = shader.fragmentShader.replace(
            "#include <common>",
            `#include <common>
varying vec3 vPos;

uniform float uProgress;
uniform float uFreq;
uniform float uAmp;
uniform float uEdge;
uniform vec3 uEdgeColor;
uniform float uEdgeIntensity;

${noiseGLSL}
`
        )

        // Dissolve discard + edge coloring (after dithering, overwrite gl_FragColor)
        shader.fragmentShader = shader.fragmentShader.replace(
            "#include <dithering_fragment>",
            `#include <dithering_fragment>

    float noise = snoise(vPos * uFreq) * uAmp;
    if (noise < uProgress) discard;

    float edgeEnd = uProgress + uEdge;
    if (noise > uProgress && noise < edgeEnd) {
        float edgeMix = 1.0 - smoothstep(uProgress, edgeEnd, noise);
        vec3 glow = uEdgeColor * uEdgeIntensity * edgeMix;
        gl_FragColor = vec4(gl_FragColor.rgb + glow, gl_FragColor.a);
    }
`
        )
    }

    mat.needsUpdate = true
    return mat
}

/* ─── Dissolve Particle System ─── */

// Procedural particle texture (radial gradient, soft circle)
let _particleTexture = null
function getParticleTexture() {
    if (_particleTexture) return _particleTexture
    const size = 64
    const canvas = document.createElement("canvas")
    canvas.width = size
    canvas.height = size
    const ctx = canvas.getContext("2d", {
        willReadFrequently: true,
    })
    const gradient = ctx.createRadialGradient(
        size / 2,
        size / 2,
        0,
        size / 2,
        size / 2,
        size / 2
    )
    gradient.addColorStop(0, "rgba(255,255,255,1)")
    gradient.addColorStop(0.3, "rgba(255,255,255,0.8)")
    gradient.addColorStop(0.7, "rgba(255,255,255,0.3)")
    gradient.addColorStop(1, "rgba(255,255,255,0)")
    ctx.fillStyle = gradient
    ctx.fillRect(0, 0, size, size)
    _particleTexture = new THREE.CanvasTexture(canvas)
    return _particleTexture
}

/**
 * Sample vertex positions from all meshes in a model.
 * Returns a flat Float32Array of [x,y,z,...] in LOCAL model space.
 * maxCount caps total particles for performance.
 */
function sampleModelPositions(model, maxCount) {
    model.updateMatrixWorld(true) // Ensure matrices are current
    const positions = []
    model.traverse((child) => {
        if (!child.isMesh || child.__isOutlineMesh) return
        const posAttr = child.geometry?.getAttribute("position")
        if (!posAttr) return
        const worldMat = child.matrixWorld.clone()
        const modelInverse = model.matrixWorld.clone().invert()
        const localMat = modelInverse.multiply(worldMat)
        const v = new THREE.Vector3()
        for (let i = 0; i < posAttr.count; i++) {
            v.set(posAttr.getX(i), posAttr.getY(i), posAttr.getZ(i))
            v.applyMatrix4(localMat)
            positions.push(v.x, v.y, v.z)
        }
    })
    const totalVerts = positions.length / 3
    if (totalVerts <= maxCount) return new Float32Array(positions)
    const stride = Math.ceil(totalVerts / maxCount)
    const sampled = []
    for (let i = 0; i < totalVerts; i += stride) {
        sampled.push(
            positions[i * 3],
            positions[i * 3 + 1],
            positions[i * 3 + 2]
        )
    }
    return new Float32Array(sampled)
}

/**
 * Create dissolve particle system.
 * Returns { points, geo, mat, state } — add points to scene, update state each frame.
 */
function createDissolveParticles(model, cfg) {
    const maxParticles = cfg.dissolveParticleMaxCount || 8000
    const initPositions = sampleModelPositions(model, maxParticles)
    const count = initPositions.length / 3

    const currentPos = new Float32Array(initPositions)
    const velocity = new Float32Array(count * 3)
    const maxOffset = new Float32Array(count)
    const dist = new Float32Array(count)
    const angle = new Float32Array(count)

    for (let i = 0; i < count; i++) {
        maxOffset[i] = Math.random() * 5.5 + 1.5
        velocity[i * 3] = Math.random() * 0.5 + 0.5
        velocity[i * 3 + 1] = Math.random() * 0.5 + 0.5
        velocity[i * 3 + 2] = Math.random() * 0.1
        dist[i] = 0.001
        angle[i] = Math.random() * Math.PI * 2
    }

    const geo = new THREE.BufferGeometry()
    geo.setAttribute(
        "position",
        new THREE.BufferAttribute(new Float32Array(initPositions), 3)
    )
    geo.setAttribute("aCurrentPos", new THREE.BufferAttribute(currentPos, 3))
    geo.setAttribute("aDist", new THREE.BufferAttribute(dist, 1))
    geo.setAttribute("aAngle", new THREE.BufferAttribute(angle, 1))

    const particleTex = getParticleTexture()

    const mat = new THREE.ShaderMaterial({
        transparent: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        uniforms: {
            uTexture: { value: particleTex },
            uPixelDensity: {
                value:
                    typeof window !== "undefined" ? window.devicePixelRatio : 1,
            },
            uProgress: { value: 0 },
            uEdge: { value: cfg.dissolveEdgeWidth || 0.8 },
            uAmp: { value: cfg.dissolveAmplitude || 16 },
            uFreq: { value: cfg.dissolveNoiseScale || 0.25 },
            uBaseSize: { value: cfg.dissolveParticleBaseSize || 80 },
            uColor: {
                value: parseColor(
                    cfg.dissolveParticleColor ||
                        cfg.dissolveEmissiveColor ||
                        "#4d9bff"
                ),
            },
        },
        vertexShader: `
${noiseGLSL}

uniform float uPixelDensity;
uniform float uBaseSize;
uniform float uFreq;
uniform float uAmp;
uniform float uEdge;
uniform float uProgress;

varying float vNoise;
varying float vAngle;

attribute vec3 aCurrentPos;
attribute float aDist;
attribute float aAngle;

void main() {
    vec3 pos = position;
    float noise = snoise(pos * uFreq) * uAmp;
    vNoise = noise;
    vAngle = aAngle;

    if (vNoise > uProgress - 2.0 && vNoise < uProgress + uEdge + 2.0) {
        pos = aCurrentPos;
    }

    vec4 modelPosition = modelMatrix * vec4(pos, 1.0);
    vec4 viewPosition = viewMatrix * modelPosition;
    vec4 projectedPosition = projectionMatrix * viewPosition;
    gl_Position = projectedPosition;

    float size = uBaseSize * uPixelDensity;
    size = size / (aDist + 1.0);
    gl_PointSize = size / -viewPosition.z;
}
`,
        fragmentShader: `
uniform vec3 uColor;
uniform float uEdge;
uniform float uProgress;
uniform sampler2D uTexture;

varying float vNoise;
varying float vAngle;

void main() {
    if (vNoise < uProgress) discard;
    if (vNoise > uProgress + uEdge) discard;

    vec2 coord = gl_PointCoord - 0.5;
    coord = coord * mat2(cos(vAngle), sin(vAngle), -sin(vAngle), cos(vAngle));
    coord = coord + 0.5;

    vec4 tex = texture2D(uTexture, coord);
    gl_FragColor = vec4(uColor * tex.rgb, tex.a);
}
`,
    })

    const points = new THREE.Points(geo, mat)
    points.frustumCulled = false

    return {
        points,
        geo,
        mat,
        state: {
            count,
            initPositions: new Float32Array(initPositions),
            currentPos,
            velocity,
            maxOffset,
            dist,
            angle,
            speed: cfg.dissolveParticleSpeed || 0.02,
            waveAmp: cfg.dissolveParticleWaveAmp || 0,
            velFactor: {
                x: cfg.dissolveParticleVelX || 2.5,
                y: cfg.dissolveParticleVelY || 2.0,
            },
        },
    }
}

/**
 * CPU-side per-frame update of particle positions.
 */
function updateDissolveParticles(pState) {
    const {
        count,
        initPositions,
        currentPos,
        velocity,
        maxOffset,
        dist,
        angle,
        speed,
        waveAmp,
        velFactor,
    } = pState
    const _v1 = _tmpParticleVecA
    const _v2 = _tmpParticleVecB

    for (let i = 0; i < count; i++) {
        const x = i * 3,
            y = i * 3 + 1,
            z = i * 3 + 2

        let vx = velocity[x] * velFactor.x
        let vy = velocity[y] * velFactor.y
        let vz = velocity[z]

        if (waveAmp > 0) {
            const px = currentPos[x],
                py = currentPos[y]
            vx += (Math.sin(py * 2) * 0.8 + Math.sin(py * 5) * 0.2) * waveAmp
            vy += (Math.sin(px * 2) * 0.6 + Math.sin(px * 1) * 0.9) * waveAmp
        }

        vx *= Math.abs(speed)
        vy *= Math.abs(speed)
        vz *= Math.abs(speed)

        currentPos[x] += vx
        currentPos[y] += vy
        currentPos[z] += vz

        _v1.set(initPositions[x], initPositions[y], initPositions[z])
        _v2.set(currentPos[x], currentPos[y], currentPos[z])
        const d = _v1.distanceTo(_v2)
        dist[i] = d
        angle[i] += 0.01

        if (d > maxOffset[i]) {
            currentPos[x] = initPositions[x]
            currentPos[y] = initPositions[y]
            currentPos[z] = initPositions[z]
        }
    }
}

/** Sync particle geometry attributes after CPU update. */
function syncParticleAttributes(pGeo, pState) {
    const cpAttr = pGeo.getAttribute("aCurrentPos")
    if (cpAttr) {
        cpAttr.array = pState.currentPos
        cpAttr.needsUpdate = true
    }
    const dAttr = pGeo.getAttribute("aDist")
    if (dAttr) {
        dAttr.array = pState.dist
        dAttr.needsUpdate = true
    }
    const aAttr = pGeo.getAttribute("aAngle")
    if (aAttr) {
        aAttr.array = pState.angle
        aAttr.needsUpdate = true
    }
}

/** Dispose particle system. */
function disposeDissolveParticles(p) {
    if (!p) return
    p.geo?.dispose()
    p.mat?.dispose()
    if (p.points?.parent) p.points.parent.remove(p.points)
}

function _startDissolveInForModel(st, cfg) {
    if (!st?.model) return false

    st.model.visible = true
    st.dissolveActive = true
    st.dissolveDirection = -1
    st.dissolveProgress = 1
    st._dissolvePendingIn = false

    st.model.traverse((child) => {
        if (!child.isMesh) return
        st.dissolveOriginalMaterials.set(child.uuid, child.material)
        const dissolveMat = createDissolveMaterial(child.material, {
            progress: mapDissolveProgress(
                1,
                cfg.dissolveAmplitude,
                cfg.dissolveEdgeWidth
            ),
            noiseScale: cfg.dissolveNoiseScale,
            amplitude: cfg.dissolveAmplitude,
            edgeWidth: cfg.dissolveEdgeWidth,
            emissiveColor: cfg.dissolveEmissiveColor,
            emissiveIntensity: cfg.dissolveEmissiveIntensity,
        })
        st.dissolveMaterials.set(child.uuid, dissolveMat)
        child.material = dissolveMat
    })

    if (cfg.dissolveParticlesEnabled) {
        disposeDissolveParticles(st.dissolveParticles)
        st.dissolveParticles = createDissolveParticles(st.model, cfg)
        st.dissolveParticles.points.position.copy(st.model.position)
        st.dissolveParticles.points.rotation.copy(st.model.rotation)
        st.dissolveParticles.points.scale.copy(st.model.scale)
        st.scene.add(st.dissolveParticles.points)
        st.dissolveParticles.mat.uniforms.uProgress.value = mapDissolveProgress(
            1,
            cfg.dissolveAmplitude,
            cfg.dissolveEdgeWidth
        )
    }

    return true
}

/**
 * Map normalized progress (0→1) to shader uProgress range based on amplitude + edge.
 * noise = snoise(pos * freq) * amp → range ≈ [-amp, +amp]
 * At t=0: uProgress = -(amp+edge) → nothing discarded (fully visible)
 * At t=1: uProgress = +(amp+edge) → everything discarded (fully dissolved)
 */
function mapDissolveProgress(t, amp, edge) {
    const range = (amp || 16) + (edge || 0.8)
    return -range + t * 2 * range
}

