/** Create a stepped gradient texture for MeshToonMaterial */
let _toonGradientCache = null
function getToonGradientMap(steps) {
    if (_toonGradientCache && _toonGradientCache._steps === steps)
        return _toonGradientCache
    const size = Math.max(steps, 2)
    const data = new Uint8Array(size)
    for (let i = 0; i < size; i++) {
        data[i] = Math.round((i / (size - 1)) * 255)
    }
    const tex = new THREE.DataTexture(data, size, 1, THREE.RedFormat)
    tex.minFilter = THREE.NearestFilter
    tex.magFilter = THREE.NearestFilter
    tex.needsUpdate = true
    tex._steps = steps
    _toonGradientCache = tex
    return tex
}

let _sketchHatchTexture = null
function getSketchHatchTexture() {
    if (_sketchHatchTexture) return _sketchHatchTexture
    const size = 256
    const canvas = document.createElement("canvas")
    canvas.width = size
    canvas.height = size
    const ctx = canvas.getContext("2d", {
        willReadFrequently: false,
    })
    if (!ctx) return null
    ctx.fillStyle = "#f3f3ef"
    ctx.fillRect(0, 0, size, size)
    ctx.strokeStyle = "rgba(0,0,0,0.42)"
    ctx.lineWidth = 3
    for (let x = -size; x < size * 2; x += 12) {
        ctx.beginPath()
        ctx.moveTo(x, size)
        ctx.lineTo(x + size, 0)
        ctx.stroke()
    }
    const tex = new THREE.CanvasTexture(canvas)
    tex.wrapS = THREE.RepeatWrapping
    tex.wrapT = THREE.RepeatWrapping
    tex.repeat.set(2, 2)
    tex.colorSpace = THREE.SRGBColorSpace
    tex.needsUpdate = true
    _sketchHatchTexture = tex
    return tex
}

function _isMeshOwnedByBone(mesh) {
    let p = mesh?.parent
    while (p) {
        if (p.isBone || p.type === "Bone") return true
        p = p.parent
    }
    return false
}

function _isMaterialPresetTarget(child) {
    if (!child?.isMesh) return false
    if (child.__isOutlineMesh) return false
    if (child.visible === false) return false
    if (_isMeshOwnedByBone(child)) return false
    if (!child.geometry) return false
    const posAttr = child.geometry.getAttribute?.("position")
    return !posAttr || posAttr.count > 3
}

function _createMaterialPresetOutlineMesh(child, outlineMat, thickness) {
    // Duplicating animated SkinnedMesh outlines is expensive and can tank scroll FPS.
    // Keep Anime/Sketch outlines on static meshes only; rigged meshes still get the stylized material.
    if (child.isSkinnedMesh) return null

    const outlineMesh = new THREE.Mesh(child.geometry, outlineMat)

    outlineMesh.__isOutlineMesh = true
    outlineMesh.castShadow = false
    outlineMesh.receiveShadow = false
    outlineMesh.frustumCulled = child.frustumCulled
    outlineMesh.scale.copy(child.scale)
    outlineMesh.scale.multiplyScalar(1 + thickness)
    outlineMesh.position.copy(child.position)
    outlineMesh.rotation.copy(child.rotation)
    outlineMesh.quaternion.copy(child.quaternion)

    if (child.morphTargetInfluences) {
        outlineMesh.morphTargetInfluences = child.morphTargetInfluences
        outlineMesh.morphTargetDictionary = child.morphTargetDictionary
    }

    return outlineMesh
}

/**
 * Detect if a material is glass (has physical transmission).
 */
function _isGlassMaterial(mat) {
    return (mat.transmission && mat.transmission > 0) || !!mat.transmissionMap
}

/**
 * Clone a glass material into a clean MeshPhysicalMaterial, preserving all glass properties.
 * If already MeshPhysicalMaterial, just clone. Otherwise, convert + copy.
 */
function _cloneAsGlassPhysical(old) {
    if (old.isMeshPhysicalMaterial) return old.clone()

    const pm = new THREE.MeshPhysicalMaterial()
    const scalarKeys = [
        "color",
        "emissive",
        "metalness",
        "roughness",
        "opacity",
        "alphaTest",
        "side",
        "transmission",
        "thickness",
        "ior",
        "transparent",
        "depthWrite",
        "attenuationColor",
        "attenuationDistance",
        "envMapIntensity",
        "emissiveIntensity",
        "clearcoat",
        "clearcoatRoughness",
        "specularIntensity",
        "specularColor",
    ]
    for (const k of scalarKeys) {
        if (old[k] !== undefined)
            pm[k] = old[k]?.clone ? old[k].clone() : old[k]
    }
    const mapKeys = [
        "map",
        "normalMap",
        "aoMap",
        "emissiveMap",
        "alphaMap",
        "transmissionMap",
        "thicknessMap",
        "roughnessMap",
        "metalnessMap",
        "clearcoatMap",
        "clearcoatRoughnessMap",
        "clearcoatNormalMap",
        "envMap",
    ]
    for (const k of mapKeys) {
        if (old[k]) pm[k] = old[k]
    }
    if (old.normalScale) pm.normalScale = old.normalScale.clone()
    return pm
}

/**
 * Apply toon-style adjustments to a glass MeshPhysicalMaterial.
 * Keeps transmission pipeline intact but makes it look more stylized.
 */
function _stylizeGlassForToon(glassMat) {
    // Cleaner, more stylized glass: lower roughness, boost env reflections
    glassMat.roughness = Math.min(glassMat.roughness, 0.15)
    glassMat.metalness = Math.max(glassMat.metalness, 0.0)
    glassMat.envMapIntensity = Math.max(glassMat.envMapIntensity ?? 1, 0.8)
    // Ensure transmission pipeline is correct (no alpha blending conflict)
    if (glassMat.transmission > 0) {
        glassMat.transparent = false
        glassMat.depthWrite = true
        glassMat.opacity = 1
    }
    glassMat.needsUpdate = true
}

/**
 * Apply toon shading preset to a model.
 * Replaces all materials with MeshToonMaterial + gradientMap.
 * Preserves original color, diffuse map, normal map, ao map from source materials.
 * Glass materials (transmission > 0) are kept as MeshPhysicalMaterial with toon-style adjustments,
 * since MeshToonMaterial does not support the transmission render pipeline.
 */
function applyToonPreset(model, preset) {
    if (!model) return
    const gradMap = getToonGradientMap(preset.steps || 4)

    model.traverse((child) => {
        if (!_isMaterialPresetTarget(child)) return

        const mats = Array.isArray(child.material)
            ? child.material
            : [child.material]
        for (let i = 0; i < mats.length; i++) {
            const old = mats[i]

            // ── Glass: keep as MeshPhysicalMaterial with toon-style tweaks ──
            if (_isGlassMaterial(old)) {
                const glassMat = _cloneAsGlassPhysical(old)
                _stylizeGlassForToon(glassMat)
                if (Array.isArray(child.material)) child.material[i] = glassMat
                else child.material = glassMat
                continue
            }

            // ── Standard opaque: convert to MeshToonMaterial ──
            const toonMat = new THREE.MeshToonMaterial({
                color: old.color
                    ? old.color.clone()
                    : new THREE.Color(0xffffff),
                gradientMap: gradMap,
                side: old.side ?? THREE.FrontSide,
            })
            // Preserve texture maps from original material
            if (old.map) toonMat.map = old.map
            if (old.normalMap) {
                toonMat.normalMap = old.normalMap
                toonMat.normalScale =
                    old.normalScale?.clone() ?? new THREE.Vector2(1, 1)
            }
            if (old.aoMap) {
                toonMat.aoMap = old.aoMap
                toonMat.aoMapIntensity = old.aoMapIntensity ?? 1
            }
            if (old.emissive) toonMat.emissive = old.emissive.clone()
            if (old.emissiveMap) toonMat.emissiveMap = old.emissiveMap
            if (old.emissiveIntensity != null)
                toonMat.emissiveIntensity = old.emissiveIntensity
            if (old.alphaMap) toonMat.alphaMap = old.alphaMap
            if (old.transparent) toonMat.transparent = old.transparent
            if (old.opacity != null) toonMat.opacity = old.opacity
            if (old.alphaTest) toonMat.alphaTest = old.alphaTest

            toonMat.needsUpdate = true
            if (Array.isArray(child.material)) child.material[i] = toonMat
            else child.material = toonMat
        }
    })
}

function applySketchPreset(model, preset) {
    if (!model) return
    const gradMap = getToonGradientMap(preset.steps || 3)
    const hatchMap = getSketchHatchTexture()
    const baseColor = parseColor(preset.color || "#f4f2ec")
    const outlineColor = parseColor(preset.outlineColor || "#050505")
    const thickness = preset.outlineThickness ?? 0.045
    const outlineMeshesToAdd = []

    removeOutlineMeshes(model)

    model.traverse((child) => {
        if (!_isMaterialPresetTarget(child)) return

        const mats = Array.isArray(child.material)
            ? child.material
            : [child.material]
        for (let i = 0; i < mats.length; i++) {
            const old = mats[i]

            if (_isGlassMaterial(old)) {
                const glassMat = _cloneAsGlassPhysical(old)
                glassMat.color = baseColor.clone()
                _stylizeGlassForToon(glassMat)
                if (Array.isArray(child.material)) child.material[i] = glassMat
                else child.material = glassMat
                continue
            }

            const sketchMat = new THREE.MeshToonMaterial({
                color: baseColor,
                gradientMap: gradMap,
                map: hatchMap,
                side: old.side ?? THREE.FrontSide,
            })
            if (old.normalMap) {
                sketchMat.normalMap = old.normalMap
                sketchMat.normalScale =
                    old.normalScale?.clone() ?? new THREE.Vector2(1, 1)
            }
            if (old.aoMap) {
                sketchMat.aoMap = old.aoMap
                sketchMat.aoMapIntensity = old.aoMapIntensity ?? 1
            }
            sketchMat.needsUpdate = true
            if (Array.isArray(child.material)) child.material[i] = sketchMat
            else child.material = sketchMat
        }

        const outlineMat = new THREE.MeshBasicMaterial({
            color: outlineColor,
            side: THREE.BackSide,
        })
        const outlineMesh = _createMaterialPresetOutlineMesh(
            child,
            outlineMat,
            thickness
        )
        if (outlineMesh) {
            outlineMeshesToAdd.push({
                parent: child.parent,
                mesh: outlineMesh,
            })
        } else {
            outlineMat.dispose()
        }
    })

    for (const entry of outlineMeshesToAdd) {
        if (entry.parent) entry.parent.add(entry.mesh)
    }
}

/**
 * Apply anime line (outline) preset to a model.
 * Uses inverted hull method: adds backface-rendered outline meshes.
 * Also applies a flat/toon base material.
 * Glass materials (transmission > 0) are preserved with outline meshes still added around them.
 */
function applyOutlinePreset(model, preset) {
    if (!model) return
    const baseColor = parseColor(preset.color || "#e8e0d8")
    const outlineColor = parseColor(preset.outlineColor || "#2a2a2a")
    const thickness = preset.outlineThickness ?? 0.06

    // First, remove any existing outline meshes from previous applications
    removeOutlineMeshes(model)

    // Apply flat/toon base material (glass preserved) + collect outline targets
    const outlineMeshesToAdd = []
    model.traverse((child) => {
        if (!_isMaterialPresetTarget(child)) return

        const mats = Array.isArray(child.material)
            ? child.material
            : [child.material]
        for (let i = 0; i < mats.length; i++) {
            const old = mats[i]

            if (_isGlassMaterial(old)) {
                // ── Glass: preserve physical material with stylized glass look ──
                const glassMat = _cloneAsGlassPhysical(old)
                _stylizeGlassForToon(glassMat)
                // Slightly more reflective for anime style
                glassMat.roughness = Math.min(glassMat.roughness, 0.1)
                if (Array.isArray(child.material)) child.material[i] = glassMat
                else child.material = glassMat
            } else {
                // ── Standard opaque: flat toon replacement ──
                const flatMat = new THREE.MeshToonMaterial({
                    color: baseColor,
                    side: THREE.FrontSide,
                })
                if (old.map) flatMat.map = old.map
                flatMat.needsUpdate = true
                if (Array.isArray(child.material)) child.material[i] = flatMat
                else child.material = flatMat
            }
        }

        // Create outline mesh (inverted hull) — always, including around glass meshes
        if (child.geometry) {
            const outlineMat = new THREE.MeshBasicMaterial({
                color: outlineColor,
                side: THREE.BackSide,
            })
            const outlineMesh = _createMaterialPresetOutlineMesh(
                child,
                outlineMat,
                thickness
            )
            if (outlineMesh) {
                outlineMeshesToAdd.push({
                    parent: child.parent,
                    mesh: outlineMesh,
                })
            } else {
                outlineMat.dispose()
            }
        }
    })

    // Add outline meshes after traversal to avoid modifying tree during traverse
    for (const entry of outlineMeshesToAdd) {
        if (entry.parent) entry.parent.add(entry.mesh)
    }
}

/**
 * Remove outline meshes created by applyOutlinePreset.
 */
function removeOutlineMeshes(model) {
    if (!model) return
    const toRemove = []
    model.traverse((child) => {
        if (child.__isOutlineMesh) toRemove.push(child)
    })
    for (const m of toRemove) {
        if (m.parent) m.parent.remove(m)
        m.geometry = null // don't dispose — shared with original
        m.material?.dispose()
    }
}

/**
 * Check if a preset is a special (non-PBR) type.
 */
function isSpecialPreset(presetKey) {
    const p = MATERIAL_PRESETS[presetKey]
    return p && p._type
}

