/* HDRI loading cache */
const hdriCache = new Map()
const hdriInFlight = new Map()

function _markSharedHDRI(texture, url) {
    if (!texture) return texture
    texture.userData = texture.userData || {}
    texture.userData.__sharedHDRIUrl = url
    return texture
}

function _isSharedHDRI(texture) {
    return !!texture?.userData?.__sharedHDRIUrl
}

function loadHDRI(renderer, url, onDone) {
    if (hdriCache.has(url)) {
        const entry = hdriCache.get(url)
        entry.lastUsed = performance.now()
        onDone(entry.texture)
        return
    }
    if (hdriInFlight.has(url)) {
        hdriInFlight.get(url).push(onDone)
        return
    }

    hdriInFlight.set(url, [onDone])
    const pmrem = new THREE.PMREMGenerator(renderer)
    pmrem.compileEquirectangularShader()
    new HDRLoader().load(
        url,
        (texture) => {
            const envMap = _markSharedHDRI(
                pmrem.fromEquirectangular(texture).texture,
                url
            )
            pmrem.dispose()
            texture.dispose()
            hdriCache.set(url, {
                texture: envMap,
                refs: 0,
                lastUsed: performance.now(),
            })
            const callbacks = hdriInFlight.get(url) || []
            hdriInFlight.delete(url)
            callbacks.forEach((cb) => cb(envMap))
        },
        undefined,
        (err) => {
            console.warn("HDRI load failed:", url, err)
            pmrem.dispose()
            const callbacks = hdriInFlight.get(url) || []
            hdriInFlight.delete(url)
            callbacks.forEach((cb) => cb(null))
        }
    )
}

function _retainHDRI(url, texture) {
    if (!url || !texture) return
    const entry = hdriCache.get(url) || {
        texture,
        refs: 0,
        lastUsed: performance.now(),
    }
    entry.texture = texture
    entry.refs = (entry.refs || 0) + 1
    entry.lastUsed = performance.now()
    hdriCache.set(url, entry)
}

function _releaseHDRI(url) {
    const entry = hdriCache.get(url)
    if (!entry) return
    entry.refs = Math.max(0, (entry.refs || 0) - 1)
    entry.lastUsed = performance.now()

    // Keep only one idle HDRI around. This avoids piling up PMREM cube maps
    // while still making the most recent preset switch cheap.
    const idle = [...hdriCache.entries()]
        .filter(([, item]) => (item.refs || 0) === 0)
        .sort((a, b) => (a[1].lastUsed || 0) - (b[1].lastUsed || 0))
    while (idle.length > 1) {
        const [oldUrl, oldEntry] = idle.shift()
        oldEntry.texture?.dispose?.()
        hdriCache.delete(oldUrl)
    }
}

function _releaseEnvironmentMap(st) {
    if (!st) return
    const envMap = st.envMap
    const envMapKey = st.envMapKey || ""
    const envMapSource = st.envMapSource || ""
    if (envMapSource === "hdri" && envMapKey) {
        _releaseHDRI(envMapKey)
    } else if (envMapSource === "procedural" && envMap) {
        st.envMap.dispose()
    }
    st.envMap = null
    st.envMapSource = ""
    st.envMapKey = ""
    st.hdriLoadingUrl = ""
}

